package org.sleepwell.app;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public final class HealthSleepTest {
 HealthSleep source(List<HealthSleep.Stage> stages){return new HealthSleep("remote-1","com.example.sleep",100000,160000,200000,0,3600,"Reported","Notes",stages);}
 @Test public void reportedAwakeKindsAreTheOnlyStagesRemovedFromDuration(){HealthSleep s=source(List.of(new HealthSleep.Stage(100000,110000,1),new HealthSleep.Stage(110000,120000,4),new HealthSleep.Stage(120000,130000,5),new HealthSleep.Stage(130000,140000,6),new HealthSleep.Stage(140000,150000,3),new HealthSleep.Stage(150000,160000,7)));assertEquals(30000,s.duration());assertEquals(2,s.awake().size());assertTrue("Provider stages remain distinct from user awake edits",s.draft().awake.isEmpty());}
 @Test public void absentStagesRemainUnreportedRatherThanInvented(){HealthSleep s=source(List.of());assertTrue(s.stages.isEmpty());assertTrue(s.awake().isEmpty());assertEquals(60000,s.duration());}
 @Test public void gapsBetweenStagesAreNotFilled(){HealthSleep s=source(List.of(new HealthSleep.Stage(100000,110000,4),new HealthSleep.Stage(150000,160000,5)));assertEquals(2,s.stages.size());assertEquals(60000,s.duration());}
 @Test public void overlapAndOutOfSessionStagesReject(){assertThrows(IllegalArgumentException.class,()->source(List.of(new HealthSleep.Stage(100000,130000,4),new HealthSleep.Stage(120000,140000,5))));assertThrows(IllegalArgumentException.class,()->source(List.of(new HealthSleep.Stage(99000,110000,4))));assertThrows(IllegalArgumentException.class,()->source(List.of(new HealthSleep.Stage(150000,160001,4))));}
 @Test public void unknownStageAndReversedSessionReject(){assertThrows(IllegalArgumentException.class,()->source(List.of(new HealthSleep.Stage(100000,110000,8))));assertThrows(IllegalArgumentException.class,()->new HealthSleep("id","com.example",2,1,0,null,null,"","",List.of()));}
 @Test public void boundedMetadataRejectsInvalidOriginsAndTooManyStages(){assertThrows(IllegalArgumentException.class,()->new HealthSleep("id","https://example.com",1000,2000,0,null,null,"","",List.of()));assertThrows(IllegalArgumentException.class,()->new HealthSleep("id","com.example",1000,2000,0,null,null,"","x".repeat(20001),List.of()));assertThrows(IllegalArgumentException.class,()->source(Collections.nCopies(HealthSleep.MAX_STAGES+1,new HealthSleep.Stage(100000,100001,0))));}
 @Test public void immutableStagesAndOriginalNotesSurviveDraftEdits(){HealthSleep s=source(new ArrayList<>(List.of(new HealthSleep.Stage(100000,110000,1))));RecordDraft d=s.draft();d.note="Local edit";d.awake.clear();assertEquals("Notes",s.notes);assertEquals(1,s.stages.size());assertThrows(UnsupportedOperationException.class,()->s.stages.clear());assertEquals(50000,s.duration());}
 @Test public void independentStartEndOffsetsRemainHistoricalAcrossDst(){HealthSleep s=source(List.of());assertEquals(Integer.valueOf(0),s.startOffset);assertEquals(Integer.valueOf(3600),s.endOffset);assertEquals("+01:00",s.zone());assertEquals(60000,s.end-s.start);}
 @Test public void noOffsetRemainsUnknownAndBadOffsetRejects(){HealthSleep s=new HealthSleep("id","com.example",1000,2000,0,null,null,"","",List.of());assertEquals("",s.zone());assertThrows(java.time.DateTimeException.class,()->new HealthSleep("id","com.example",1000,2000,0,70000,null,"","",List.of()));}
}
